/**
 * The packed fallback filter-placement rule ({@link PackedFilterRules}) may only push a filter into one operand of a
 * join when every filter variable is either assured by that operand or cannot be bound by the sibling operand. Using
 * the operand's <em>possible</em> output mask pushes {@code FILTER(?x = ?y)} onto a {@code LeftJoin} whose optional
 * side only maybe binds {@code ?x}, although the sibling pattern {@code ?s :r ?x} binds it for every row: rows whose
 * OPTIONAL left {@code ?x} unbound are then dropped instead of being filtered on the joined value.
 *
 * <p>
 * The fallback rule is reached only when the dense join lattice does not complete (tight work budget, or more than
 * {@code DENSE_FACTOR_LIMIT} factors), so the tests sweep the work budget and the region width. Every selected plan is
 * evaluated differentially against the unoptimized algebra.
 */
class PackedFilterPushAssuredMaskTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIXES = "PREFIX : <urn:t:>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";

	private static final String QUERY = "SELECT ?s ?x ?y WHERE { ?s :p ?y OPTIONAL { ?s :q ?x } ?s :r ?x FILTER(?x = ?y) }";

	private static final List<String> EXPECTED = List.of(
			"s=urn:t:a|x=\"1\"^^<http://www.w3.org/2001/XMLSchema#int>|y=\"1\"^^<http://www.w3.org/2001/XMLSchema#int>",
			"s=urn:t:b|x=\"2\"^^<http://www.w3.org/2001/XMLSchema#int>|y=\"2\"^^<http://www.w3.org/2001/XMLSchema#int>");

	/** Unbound statement patterns are expensive; a pattern whose subject is bound by the prefix is a point lookup. */
	private static final PackedCostModel SUBJECT_LOOKUP_COSTS = new PackedCostModel() {
		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isStatementPattern(relationId) ? 10_000.0d : Double.NaN;
		}

		@Override
		public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
				PackedCostEstimate output) {
			if (!query.isStatementPattern(relationId)) {
				return;
			}
			if (context.prefixRelationCount() != 0 && (query.prefixBindsStatementComponent(context, relationId, 0)
					|| query.prefixBindsStatementComponent(context, relationId, 2))) {
				output.setContextualRows(1.0d, 1.0d);
			} else {
				output.setRows(10_000.0d, 10_000.0d);
			}
		}
	};

	/** Statement patterns are large; every FILTER is estimated to be highly selective, rewarding early placement. */
	private static final PackedCostModel SELECTIVE_FILTER_COSTS = new PackedCostModel() {
		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isStatementPattern(relationId) ? 1_000.0d : Double.NaN;
		}

		@Override
		public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
				PackedCostEstimate output) {
			if (query.isFilter(relationId)) {
				output.setRows(1.0d, output.workRows());
			}
		}
	};

	private static Model data(int extraPatterns) {
		Model data = new LinkedHashModel();
		add(data, "a", "p", VF.createLiteral(1));
		add(data, "a", "r", VF.createLiteral(1));
		add(data, "b", "p", VF.createLiteral(2));
		add(data, "b", "q", VF.createLiteral(2));
		add(data, "b", "r", VF.createLiteral(2));
		add(data, "c", "p", VF.createLiteral(3));
		add(data, "c", "q", VF.createLiteral(4));
		add(data, "c", "r", VF.createLiteral(3));
		for (int i = 0; i < extraPatterns; i++) {
			for (String s : List.of("a", "b", "c")) {
				add(data, s, "f" + i, VF.createIRI("urn:t:v" + i));
			}
		}
		return data;
	}

	/** The optional group is a deep-left factor: {@code Join(Join(LeftJoin(p, q), r), f0 ...)}. */
	private static String leadingOptionalQuery(int extraPatterns, String filter) {
		return "SELECT ?s ?x ?y WHERE { ?s :p ?y OPTIONAL { ?s :q ?x } ?s :r ?x ." + extraPatterns(extraPatterns) + " "
				+ filter + " }";
	}

	/**
	 * The optional group is the trailing operand of the filter's direct join child:
	 * {@code Filter(Join(Join(r, f0 ... fN), LeftJoin(p, q)))}. With more than {@code DENSE_FACTOR_LIMIT} factors the
	 * dense lattice declines the region and the binary fallback rule decides the placement; the LeftJoin operand only
	 * possibly binds {@code ?x} while the sibling join binds it for every row.
	 */
	private static String trailingOptionalQuery(int extraPatterns, String thirdPattern, String filter) {
		return "SELECT ?s ?x ?y WHERE { " + thirdPattern + " ." + extraPatterns(extraPatterns)
				+ " { ?s :p ?y OPTIONAL { ?s :q ?x } } " + filter + " }";
	}

	private static String extraPatterns(int extraPatterns) {
		StringBuilder patterns = new StringBuilder();
		for (int i = 0; i < extraPatterns; i++) {
			patterns.append(" ?s :f").append(i).append(" ?w").append(i).append(" .");
		}
		return patterns.toString();
	}

	private static final long[] WORK_LIMITS = { 1L, 8L, 64L, 512L, 4096L, Long.MAX_VALUE };

	@Test
	void latticeCoveredRegionKeepsFilterAboveMaybeBoundOptionalVariable() {
		Model data = data(0);
		TupleExpr original = parse(QUERY);
		List<String> reference = evaluate(data, original);
		assertEquals(EXPECTED, reference, "reference oracle disagrees with hand-computed bag");
		assertEquals(List.of(), planningFailures(data, original, reference), "reference=" + reference);
	}

	@Test
	void latticeCoveredTrailingOptionalGroupKeepsFilterAboveMaybeBoundOptionalVariable() {
		for (int extra : new int[] { 0, 3 }) {
			Model data = data(extra);
			TupleExpr original = parse(trailingOptionalQuery(extra, "?s :r ?x", "FILTER(?x = ?y)"));
			List<String> reference = evaluate(data, original);
			assertEquals(EXPECTED, reference, "reference oracle disagrees with hand-computed bag");
			assertEquals(List.of(), planningFailures(data, original, reference),
					"extra=" + extra + " reference=" + reference);
		}
	}

	@Test
	void deepLeftOptionalInWideRegionKeepsFilterAboveMaybeBoundOptionalVariable() {
		Model data = data(18);
		TupleExpr original = parse(leadingOptionalQuery(18, "FILTER(?x = ?y)"));
		List<String> reference = evaluate(data, original);
		assertEquals(EXPECTED, reference, "reference oracle disagrees with hand-computed bag");
		assertEquals(List.of(), planningFailures(data, original, reference), "reference=" + reference);
	}

	@Test
	void fallbackPlacementInWideRegionKeepsFilterAboveMaybeBoundOptionalVariable() {
		Model data = data(18);
		TupleExpr original = parse(trailingOptionalQuery(18, "?s :r ?x", "FILTER(?x = ?y)"));
		List<String> reference = evaluate(data, original);
		assertEquals(EXPECTED, reference, "reference oracle disagrees with hand-computed bag");
		assertEquals(List.of(), planningFailures(data, original, reference), "reference=" + reference);
	}

	@Test
	void fallbackPlacementInWideRegionKeepsSameTermFilterAboveMaybeBoundOptionalVariable() {
		Model data = data(18);
		TupleExpr original = parse(trailingOptionalQuery(18, "?s :r ?x", "FILTER(sameTerm(?x, ?y))"));
		List<String> reference = evaluate(data, original);
		assertEquals(EXPECTED, reference, "reference oracle disagrees with hand-computed bag");
		assertEquals(List.of(), planningFailures(data, original, reference), "reference=" + reference);
	}

	/**
	 * Positive guard: {@code ?y} is assured by the LeftJoin operand (its left argument binds it) and absent from the
	 * sibling join, so the fallback rule may still push the filter onto the LeftJoin; the result must be unchanged.
	 */
	@Test
	void fallbackPlacementStillPushesFilterOntoAssuringOperand() {
		Model data = data(18);
		TupleExpr original = parse(trailingOptionalQuery(18, "?s :r ?z", "FILTER(?y = 1)"));
		List<String> reference = evaluate(data, original);
		assertEquals(1, reference.size(), "reference=" + reference);
		assertEquals(List.of(), planningFailures(data, original, reference), "reference=" + reference);
	}

	/**
	 * Positive guard: {@code ?x} is only possibly bound by the LeftJoin operand but the sibling join cannot bind it, so
	 * pushing the filter onto the LeftJoin is sound (unbound {@code ?x} fails the filter either way).
	 */
	@Test
	void fallbackPlacementStillPushesFilterWhenSiblingCannotBindTheVariable() {
		Model data = data(18);
		TupleExpr original = parse(trailingOptionalQuery(18, "?s :r ?z", "FILTER(?x = ?y)"));
		List<String> reference = evaluate(data, original);
		assertEquals(1, reference.size(), "reference=" + reference);
		assertEquals(List.of(), planningFailures(data, original, reference), "reference=" + reference);
	}

	/** Plans the query under both cost models and the work-limit sweep; returns every plan that changes the bag. */
	private static List<String> planningFailures(Model data, TupleExpr original, List<String> reference) {
		List<String> failures = new ArrayList<>();
		for (PackedCostModel costs : List.of(SUBJECT_LOOKUP_COSTS, SELECTIVE_FILTER_COSTS)) {
			TupleExpr selected = PackedCascadesPlanner
					.optimize(original.clone(), OptimizationGoal.root(original, null), costs)
					.selectedPlan();
			List<String> actual = evaluate(data, selected);
			if (!reference.equals(actual)) {
				failures.add((costs == SUBJECT_LOOKUP_COSTS ? "subject-lookup costs" : "selective-filter costs")
						+ " -> " + actual + "\n" + selected);
			}
		}
		for (long workLimit : WORK_LIMITS) {
			TupleExpr selected = PackedCascadesPlanner.optimize(original.clone(), workLimit, Long.MAX_VALUE)
					.selectedPlan();
			List<String> actual = evaluate(data, selected);
			if (!reference.equals(actual)) {
				failures.add("workLimit=" + workLimit + " -> " + actual + "\n" + selected);
			}
		}
		return failures;
	}

	private static TupleExpr parse(String query) {
		return new SPARQLParser().parseQuery(PREFIXES + query, "urn:t:").getTupleExpr();
	}

	private static List<String> evaluate(Model data, TupleExpr expression) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
					Value object, Resource... contexts) {
				return new CloseableIteratorIteration<>(data.getStatements(subject, predicate, object, contexts)
						.iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		QueryRoot root = expression instanceof QueryRoot queryRoot ? queryRoot.clone()
				: new QueryRoot(expression.clone());
		List<String> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = new StrictEvaluationStrategy(source, null).precompile(root)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindings.getBindingNames()) {
					Value value = bindings.getValue(name);
					if (value != null) {
						sorted.put(name, value.toString());
					}
				}
				StringBuilder builder = new StringBuilder();
				sorted.forEach((name, value) -> {
					if (builder.length() > 0) {
						builder.append('|');
					}
					builder.append(name).append('=').append(value);
				});
				rows.add(builder.toString());
			}
		}
		Collections.sort(rows);
		return rows;
	}

	private static void add(Model model, String subject, String predicate, Value object) {
		model.add(VF.createIRI("urn:t:" + subject), VF.createIRI("urn:t:" + predicate), object);
	}
}
